(require '[seon.db :as db] '[seon.cluster.boot :as boot] '[seon.cluster.store :as store] '[seon.cluster.registry :as registry] '[seon.fn :as index] '[seon.fn.analyzer :as analyzer] '[seon.program :as program] '[seon.schema :as schema] '[seon.test-support :as support] '[seon.id :as id] '[clojure.java.io :as io] '[clojure.string :as str] '[clj-kondo.impl.cache :as kondo.cache] '[clj-kondo.impl.core :as kondo.core] '[clj-kondo.core :as clj-kondo] '[clj-kondo.core :as kondo] '[cognitect.transit :as transit])
(declare content-probe-dir content-probe-source content-probe-cache content-probe-result content-probe-root content-probe-analysis invoke-after)
(do (require '[clojure.java.io :as io] '[seon.fn.analyzer :as analyzer]) (require '[clj-kondo.core :as kondo] '[clj-kondo.impl.cache :as kondo.cache] '[clj-kondo.impl.core :as kondo.core]) (def content-probe-dir (.toFile (java.nio.file.Files/createTempDirectory (.toPath (io/file "tmp")) "astra-analysis-content-" (make-array java.nio.file.attribute.FileAttribute 0)))) (def content-probe-source (io/file content-probe-dir "writer.cljc")) (spit content-probe-source (slurp (io/resource "datahike/writer.cljc"))) (def content-probe-cache (.getPath (io/file content-probe-dir "cache"))) (def content-probe-result (kondo/run! {:lint [(.getPath content-probe-source)] :cache-dir content-probe-cache :config-dir ".clj-kondo" :config {:output {:analysis true :canonical-paths true}}})) (def content-probe-root (.getPath (kondo.core/resolve-cache-dir ".clj-kondo" true content-probe-cache))) (#'analyzer/record-entry-digests! content-probe-root content-probe-result) (let [mtime (.lastModified content-probe-source)] (spit content-probe-source (str (slurp content-probe-source) "\n; changed content, preserved time\n")) (.setLastModified content-probe-source mtime)) (def content-probe-analysis {:analysis {:namespace-definitions [{:name 'datahike.writer :filename (.getPath content-probe-source)}] :namespace-usages [{:to 'datahike.writer}]}}) (let [start (System/nanoTime) result (#'analyzer/stale-cache-entries content-probe-root false content-probe-analysis)] {:stale (:seon.fn.analyzer/stale result) :ms (/ (- (System/nanoTime) start) 1e6)}))
(let [copy (io/file content-probe-dir "writer.cljc")
      _ (spit copy (str (slurp (io/resource "datahike/writer.cljc")) "\n(defn astra-stale-proof-only [] nil)\n"))
      cache content-probe-cache
      raw (kondo/run! {:lint [(.getPath copy)] :cache-dir cache :config-dir ".clj-kondo" :config {:output {:analysis true :canonical-paths true}}})
      _ (#'analyzer/record-entry-digests! content-probe-root raw)
      caller (io/file content-probe-dir "caller.clj")
      _ (spit caller "(ns astra.cache-caller (:require [datahike.writer :as writer]))\n(defn f [] writer/transact!)\n")
      cached? (fn [] (boolean (some #{'astra-stale-proof-only} (tree-seq coll? seq (kondo.cache/from-cache-1 content-probe-root :cljc 'datahike.writer)))))
      parent-start (System/nanoTime)
      parent (#'analyzer/invoke-kondo {:lint [(.getPath caller)] :cache-dir cache})
      parent-ms (/ (- (System/nanoTime) parent-start) 1e6)
      old-entry? (cached?)
      candidate-start (System/nanoTime)
      candidate (invoke-after {:lint [(.getPath caller)] :cache-dir cache})
      candidate-ms (/ (- (System/nanoTime) candidate-start) 1e6)
      facts #(mapv (fn [row] (select-keys row [:ns :name :fixed-arities])) (get-in % [:analysis :var-definitions]))]
  {:parent-ms parent-ms :candidate-ms candidate-ms
   :parent-stale-entry? old-entry? :candidate-stale-entry? (cached?)
   :same-caller-facts? (= (facts parent) (facts candidate))
   :rebuilt (:seon.fn.analyzer/rebuilt (:seon.fn.analyzer/cache candidate))})
(let [options {:lint [(.getPath (io/file content-probe-dir "caller.clj"))] :cache-dir content-probe-cache}] (mapv (fn [_] (mapv (fn [[label f]] (let [start (System/nanoTime) result (f options)] {:label label :ms (/ (- (System/nanoTime) start) 1e6) :rebuilt (:seon.fn.analyzer/rebuilt (:seon.fn.analyzer/cache result))})) [[:parent #'analyzer/invoke-kondo] [:candidate invoke-after]])) (range 3)))
